// Camouflage
// For the #WCCChallenge «Zoo» (join the discord! https://discord.gg/S8c7qcjw2b)
//
// Just playing with DIFFERENCE blend mode, and using several fonts whose characters are animal silhouettes
// 
// Font credits:
// Afrika Wildlife by Fonts of Afrika https://www.fontspace.com/afrika-wildlife-b-mammals2-font-f3364
// Animal Silhouettes by Intellecta Design https://www.fontspace.com/animal-silhouettes-three-font-f22684
// Aussie Icons by Web Dog https://www.fontspace.com/aussieicons-font-f5373
// Birds of a Feather by Iconian Fonts https://www.fontspace.com/birds-of-a-feather-font-f33001
// WWSafari by WindWalker64 https://www.fontspace.com/wwsafari-font-f3403
// Zoobats by Manfred Klein https://www.fontspace.com/zoobats-font-f9076
// Zoologic by Iconian Fonts https://www.fontspace.com/zoologic-font-f32864


let currentLayout
let layouts = ['layoutVertical', 'layoutHorizontal', 'layoutCircular']
let letterData = [] // Store letter info for hover detection
let hoveredLetter = null

let lowercaseAlphabet = 'abcdefghijklmnopqrstuvwxyz'
let lowerAndUpperAlphabet = lowercaseAlphabet + lowercaseAlphabet.toUpperCase()
const availableFonts = {
  './AnimalSilhouettesThree-n6oJ.ttf': { alphabet: lowerAndUpperAlphabet },
  './AfrikaWildlifeBMammals2-9MJj.ttf': { alphabet: lowerAndUpperAlphabet },
  './BirdsOfAFeather-rMqB.otf': { alphabet: lowerAndUpperAlphabet },
  './Zoologic-aRX9.otf': { alphabet: lowerAndUpperAlphabet },
  './Aussieicons-YXqa.ttf': { alphabet: lowercaseAlphabet },
  './Wwsafari-OGj6.ttf': { alphabet: lowercaseAlphabet },
  './Zoobats-oXr0.ttf': { alphabet: lowerAndUpperAlphabet },
}
let palette = ["#f94144","#f3722c","#f8961e","#f9844a","#f9c74f","#90be6d","#43aa8b","#4d908e","#577590","#277da1"]

async function setup () {
  createCanvas(windowWidth, windowHeight)
  let fontNames = Object.keys(availableFonts)
  await Promise.all(fontNames.map(async (fontName) => {
    let f = await loadFont(fontName)
    availableFonts[fontName].font = f
    availableFonts[fontName].alphabet = availableFonts[fontName].alphabet.split('')
  })) 
  pixelDensity(1)
  currentLayout = random(layouts)
  drawCurrentLayout()
}

function drawCurrentLayout() {
  clear()
  background(0)
  letterData = [] // Clear previous letter data

  if (currentLayout === 'layoutVertical') {
    layoutVertical()
  } else if (currentLayout === 'layoutHorizontal') {
    layoutHorizontal()
  } else if (currentLayout === 'layoutCircular') {
    layoutCircular()
  }
}

function mousePressed() {
  currentLayout = random(layouts)
  drawCurrentLayout()
}

function storeLetter(x, y, char, fontName, fontSize, rotation = 0) {
  let highlightColor = random(palette)
  letterData.push({
    centerX: x,
    centerY: y,
    character: char,
    fontName: fontName,
    fontSize: fontSize,
    rotation: rotation,
    highlightColor: highlightColor
  })
}

function layoutVertical() {
  let defaultTextPointSize = 500
  background(0)
  blendMode(DIFFERENCE)
  fill(255)
  strokeWeight(1)
  textAlign(CENTER, TOP)

  let columns = generateCenteredDivisions(width, width / 20, width / 12)
  for (let i = 0; i < columns.length - 1; i++) {
    let x = columns[i]
    let w = columns[i + 1] - x
    // rect(x, 0, w, height)
    let y = -random(height / 10, height / 5)
    while (y < height) {
      let randomFontName = random(Object.keys(availableFonts))
      let randomLetter = random(availableFonts[randomFontName].alphabet)
      let bounds

      textFont(availableFonts[randomFontName].font)
      textSize(defaultTextPointSize)

      bounds = textBounds(randomLetter, x + w / 2, y)
      let newTextPointSize = w * defaultTextPointSize / bounds.w // Adjust the text size to fit the column width
      let finalTextSize = newTextPointSize * random(1.5, 2)
      textSize(finalTextSize)
      text(randomLetter, x + w / 2, y)

      // Store letter data for hover detection
      storeLetter(x + w / 2, y, randomLetter, randomFontName, finalTextSize, 0)

      let newBounds = textBounds(randomLetter, x + w / 2, y)
      y += newBounds.h * 0.8
    }

  }


}

function layoutHorizontal() {
  let defaultTextPointSize = 500
  background(0)
  blendMode(DIFFERENCE)
  fill(255)
  strokeWeight(1)
  textAlign(LEFT, CENTER)

  let rows = generateCenteredDivisions(height, height / 15, height / 8)
  for (let i = 0; i < rows.length - 1; i++) {
    let y = rows[i]
    let h = rows[i + 1] - y
    // rect(0, y, width, h)
    let x = -random(width / 10, width / 5)
    while (x < width) {
      let randomFontName = random(Object.keys(availableFonts))
      let randomLetter = random(availableFonts[randomFontName].alphabet)
      let bounds

      textFont(availableFonts[randomFontName].font)
      textSize(defaultTextPointSize)

      bounds = textBounds(randomLetter, x, y + h / 2)
      let newTextPointSize = h * defaultTextPointSize / bounds.h // Adjust the text size to fit the row height
      let finalTextSize = newTextPointSize * random(1.5, 2)
      textSize(finalTextSize)
      text(randomLetter, x, y + h / 2)

      // Store letter data for hover detection
      storeLetter(x, y + h / 2, randomLetter, randomFontName, finalTextSize, 0)

      let newBounds = textBounds(randomLetter, x, y + h / 2)
      x += newBounds.w * 0.8
    }
  }


}

function layoutCircular() {
  background(0)
  blendMode(DIFFERENCE)
  fill(255)
  strokeWeight(1)
  textAlign(CENTER, CENTER)

  let centerX = width / 2
  let centerY = height / 2
  let maxRadius = dist(0, 0, width, height) / 2

  let radius = random(maxRadius / 10, maxRadius / 5) / 2
  let defaultTextPointSize = 500

  // Draw a single letter in the center
  let randomFontName = random(Object.keys(availableFonts))
  let randomLetter = random(availableFonts[randomFontName].alphabet)
  textFont(availableFonts[randomFontName].font)
  let centerTextSize = radius * 2
  textSize(centerTextSize)
  text(randomLetter, centerX, centerY)

  // Store center letter data
  storeLetter(centerX, centerY, randomLetter, randomFontName, centerTextSize, 0)

  while (radius < maxRadius) {
    let angle = 0
    let ringHeight = random(maxRadius / 10, maxRadius / 5)

    while (angle < TAU) { // Allow for more than one full rotation
      let randomFontName = random(Object.keys(availableFonts))
      let randomLetter = random(availableFonts[randomFontName].alphabet)

      textFont(availableFonts[randomFontName].font)
      textSize(defaultTextPointSize)

      let bounds = textBounds(randomLetter, 0, 0)

             // Calculate the fontSize to match the ring height
       let newTextPointSize = ringHeight * defaultTextPointSize / bounds.h
       let finalTextSize = newTextPointSize * random(1.5, 2)
       textSize(finalTextSize)

       let x = centerX + cos(angle) * radius
       let y = centerY + sin(angle) * radius
       let rotation = angle + PI/2 // Rotate text to be tangent to circle

       push()
       translate(x, y)
       rotate(rotation)
       text(randomLetter, 0, 0)
       pop()

       // Store letter data for hover detection
       storeLetter(x, y, randomLetter, randomFontName, finalTextSize, rotation)

       // Calculate next angle based on character width on circumference
       let newBounds = textBounds(randomLetter, 0, 0)
       angleStep = (newBounds.w * 0.8) / radius // Convert width to angle
       angle += angleStep
    }
    radius += ringHeight * 0.8
  }
}


function windowResized () {
  resizeCanvas(windowWidth, windowHeight)
  drawCurrentLayout()
}

function mouseMoved() {
  // Find the closest letter to the mouse
  let closestLetter = null
  let closestDistance = Infinity

  for (let letter of letterData) {
    let d = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), letter.centerX, letter.centerY)
    if (d < closestDistance) {
      closestDistance = d
      closestLetter = letter
    }
  }

  // Only update if the hovered letter changed
  if (hoveredLetter !== closestLetter) {
    hoveredLetter = closestLetter
    redrawWithHighlight()
  }
}

function redrawWithHighlight() {
  // Redraw from stored letter data
  clear()
  background(0)
  blendMode(DIFFERENCE)
  fill(255)

  // Draw all letters in white
  for (let letter of letterData) {
    push()
    textFont(availableFonts[letter.fontName].font)
    textSize(letter.fontSize)

    if (letter.rotation === 0) {
      // For vertical and horizontal layouts
      if (currentLayout === 'layoutVertical') {
        textAlign(CENTER, TOP)
      } else {
        textAlign(LEFT, CENTER)
      }
      text(letter.character, letter.centerX, letter.centerY)
    } else {
      // For circular layout with rotation
      textAlign(CENTER, CENTER)
      translate(letter.centerX, letter.centerY)
      rotate(letter.rotation)
      text(letter.character, 0, 0)
    }
    pop()
  }

  // Draw highlighted letter on top
  if (hoveredLetter) {
    drawHighlightedLetter()
  }
}

function drawHighlightedLetter() {
  if (!hoveredLetter) return

  push()
  // Set highlight color
  fill(hoveredLetter.highlightColor)
  blendMode(BLEND) // Use normal blend mode for highlight

  // Set font and size
  textFont(availableFonts[hoveredLetter.fontName].font)
  textSize(hoveredLetter.fontSize)

  if (hoveredLetter.rotation === 0) {
    // For vertical and horizontal layouts
    if (currentLayout === 'layoutVertical') {
      textAlign(CENTER, TOP)
    } else {
      textAlign(LEFT, CENTER)
    }
    text(hoveredLetter.character, hoveredLetter.centerX, hoveredLetter.centerY)
  } else {
    // For circular layout with rotation
    textAlign(CENTER, CENTER)
    translate(hoveredLetter.centerX, hoveredLetter.centerY)
    rotate(hoveredLetter.rotation)
    text(hoveredLetter.character, 0, 0)
  }

  pop()
}

function generateCenteredDivisions(N, minVal, maxVal) {
  const positions = [N / 2];

  let pos = N / 2;
  while (pos < N) {
    pos += random(minVal, maxVal);
    positions.push(pos);
  }

  pos = N / 2;
  while (pos > 0) {
    pos -= random(minVal, maxVal);
    positions.push(pos);
  }

  positions.sort((a, b) => a - b);
  return positions;
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

